#include <iostream>
using namespace std;

class Point {
public:
    int x;
    int y;
    Point(int a, int b) { x = a; y = b; }
};

int main() {   //@ @layout open:uml_visualizer
    Point p(3, 4);   //@ @tts [next] 建立一個點，座標是三和四
    cout << p.x << endl;   //@ @guide uml:p @tts [next] 這是 p 現在的樣子
    p.x = 10;   //@ @guide uml:p @tts [next] 把 x 改成十
    cout << p.x << endl;   //@ @guide uml:p @tts [next] x 變成十了
    return 0;   //@ @tts [continue] 程式結束
}
